import React, { useState, useRef, useCallback } from "react"
import { connect } from "react-redux"
import moment from "moment"
import { Row, Select, DatePicker, Form } from "antd"

import { DashboardFilterStyle } from "./component.style"
import policyActions from "../../../../redux/policy/action"

const { getProductsList, getPackagesList } = policyActions

const FormItem = Form.Item
const { Option } = Select

const DATE_FORMAT = "YYYY-MM-DD"

const DashboardFilters = ({
  fetch,
  getProductsList,
  getPackagesList,
  partnersList = [],
  productsList = [],
  productListLoading,
  partnerListLoading,
  packageListLoading,
  packagesList = []
}) => {
  const [values, setFormValues] = useState({})
  const formRef = useRef()

  const handleFieldsChange = useCallback(
    (a, values) => {
      setFormValues(values)
      fetch(values)
    },
    [setFormValues, fetch]
  )

  const handlePartnerChange = useCallback(
    (partner) => {
      formRef.current.resetFields(["product", "packages"])
      getProductsList({
        query: {
          partnerCodes: partner
        }
      })
    },
    [formRef, getProductsList]
  )

  const handleProductChange = useCallback(
    (product = []) => {
      if (!product.length) {
        formRef.current.resetFields(["packages"])
      }
      getPackagesList({
        query: {
          partnerCode: values.partner,
          productKey: product.join(",")
        }
      })
    },
    [formRef, getPackagesList, values]
  )

  return (
    <DashboardFilterStyle>
      <Form ref={formRef} onValuesChange={handleFieldsChange}>
        <Row>
          <div>
            <div className="head">From</div>
            <FormItem
              name="createdatStart"
              className="filter"
              initialValue={moment().clone().subtract(7, "days")}
            >
              <DatePicker allowClear={false} format={DATE_FORMAT} />
            </FormItem>
          </div>
          <div>
            <div className="head">To</div>
            <FormItem
              name="createdatEnd"
              colon={false}
              className="filter"
              initialValue={moment()}
            >
              <DatePicker allowClear={false} format={DATE_FORMAT} />
            </FormItem>
          </div>
          <div>
            <div className="head">Partner</div>
            <FormItem name="partner" className="filter">
              <Select
                showSearch
                placeholder="Select Partner"
                optionFilterProp="children"
                allowClear
                loading={!!partnerListLoading}
                disabled={!!partnerListLoading}
                dropdownMatchSelectWidth={false}
                onChange={handlePartnerChange}
                filterOption={(input, option) =>
                  option.children.toLowerCase().indexOf(input.toLowerCase()) >=
                  0
                }
              >
                {partnersList?.map(({ name, code }) => (
                  <Option key={code} value={code}>
                    {name}
                  </Option>
                ))}
              </Select>
            </FormItem>
          </div>
          <div>
            <div className="head">Product</div>
            <FormItem name="product" className="filter">
              <Select
                showSearch
                placeholder="Select Products"
                mode="multiple"
                optionFilterProp="children"
                allowClear
                loading={!!productListLoading}
                disabled={!!productListLoading}
                dropdownMatchSelectWidth={false}
                onChange={handleProductChange}
                filterOption={(input, option) =>
                  option.children.toLowerCase().indexOf(input.toLowerCase()) >=
                  0
                }
              >
                {productsList?.map(({ display_name: displayName, name }) => (
                  <Option key={name} value={name}>
                    {displayName}
                  </Option>
                ))}
              </Select>
            </FormItem>
          </div>
          <div>
            <div className="head">Package</div>
            <FormItem name="packages" className="filter">
              <Select
                showSearch
                placeholder="Select Package"
                mode="multiple"
                optionFilterProp="children"
                allowClear
                loading={!!packageListLoading}
                disabled={!!packageListLoading}
                dropdownMatchSelectWidth={false}
                filterOption={(input, option) =>
                  option.children.toLowerCase().indexOf(input.toLowerCase()) >=
                  0
                }
              >
                {packagesList?.map(
                  ({ package_name: displayName, package_code, id }) => (
                    <Option key={id} value={package_code}>
                      {displayName}
                    </Option>
                  )
                )}
              </Select>
            </FormItem>
          </div>
        </Row>
      </Form>
    </DashboardFilterStyle>
  )
}

export default connect(
  (state) => ({
    partnerListLoading: state.Loading.GET_PARTNERS_LIST,
    partnersList: state.Policy.partnersList,

    productListLoading: state.Loading.GET_PRODUCTS_LIST,
    packageListLoading: state.Loading.GET_PACKAGES_LIST,
    productsList: state.Policy.productsList,
    packagesList: state.Policy.packagesList
  }),
  {
    getProductsList,
    getPackagesList
  }
)(DashboardFilters)
