import React, { Component } from 'react'
import { connect } from 'react-redux'
import moment from 'moment-timezone'
import { LineChart, XAxis, YAxis, Tooltip, Legend, Line, ResponsiveContainer, CartesianGrid } from 'recharts'
import { DashboardGraphStyle } from './component.style'
import { map } from 'lodash'
import { STROKE_COLORS } from '../../../../../constants/randomColors'

class DashboardGraph extends Component {
  render() {
    const { data, productList } = this.props
    var lineData = map(productList, function (value, index) {
      return <Line
        key={value}
        type='monotone'
        dataKey={value}
        stroke={STROKE_COLORS[index]}
      />
    })

    return (
      <DashboardGraphStyle>
        <ResponsiveContainer width='100%' height={400}>
          <LineChart data={data} margin={{ top: 5, right: 30, left: 0, bottom: 10 }}>
            <XAxis dataKey='created_at' tickFormatter={value => moment(value).tz('Asia/Jakarta').format('DD MMMM')} />
            <YAxis label={{value: 'Number of policies', angle: -90, position: 'insideLeft' }} />
            <CartesianGrid strokeDasharray='3 3' />
            <Tooltip />
            <Legend iconType='circle' />
            {lineData}
          </LineChart>
        </ResponsiveContainer>
      </DashboardGraphStyle>
    )
  }
}

export default connect(state => ({
}), {
})(DashboardGraph)
