import React, { Component } from 'react'
import { connect } from 'react-redux'
import { find, get } from 'lodash'
import { Table } from 'antd'

import { DataTableStyle } from './component.style'

class DataTable extends Component {
  getGroupedData = () => {
    const { data: policyData = [], claimDashboardData, product = [] } = this.props
    let finalData = []
    policyData.forEach((element, index) => {
      const { partner_key: partnerKey } = element
      let claimPartnerData = undefined
      if (product.length > 0) {
        claimPartnerData = find(claimDashboardData, { products: get(element, 'product_key') })
      } else {
        claimPartnerData = find(claimDashboardData, { partners: partnerKey })
      }
      let tempData = {}
      if (claimPartnerData) {
        tempData = {
          id: index,
          ...element,
          ...claimPartnerData
        }
      } else {
        tempData = {
          id: index,
          ...element
        }
      }
      finalData.push(tempData)
    })

    return finalData
  }

  render() {
    const { product = [] } = this.props
    const columns = [
      {
        title: product.length > 0 ? 'Product' : 'Partner',
        dataIndex: product.length > 0 ? 'product_key' : 'partner_key',
        key: 'partner_key'
      }, {
        title: 'GWP',
        dataIndex: 'paymentSum',
        key: 'paymentSum'
      }, {
        title: 'Total Policies',
        dataIndex: 'policiesCount',
        key: 'policiesCount'
      }, {
        title: 'Total Settled Claims',
        dataIndex: 'total_settled_claims',
        key: 'total_settled_claims',
      }, {
        title: 'Claim Amount',
        dataIndex: 'claim_amount',
        key: 'claim_amount',
        render: claimAmount => claimAmount && new Intl.NumberFormat('id-ID', { currency: 'IDR' }).format(claimAmount)
      }
    ]

    return (
      <DataTableStyle>
        <Table
          columns={columns}
          dataSource={this.getGroupedData()}
          rowKey='id'
        />
      </DataTableStyle>
    )
  }
}

export default connect(state => ({
}), {
})(DataTable)
