import React, { Component } from 'react'
import { Row, Col } from 'antd'

import { CountStyle } from './component.style'
import { CardCount } from '../../../../../components/StyledComponents'
import { GENERIC_IMAGES } from '../../../../../constants/images'

class Count extends Component {
  render() {
    const { totalClaimAmount = 0, totalPolicies = 0, totalTransactionValue = 0, currency } = this.props

    return (
      <CountStyle>
        <Row justify="space-between" gutter={[40, 16]}>
          <Col flex="1 0 25%" className="column">
            <CardCount
              icon={<img width="32" src={GENERIC_IMAGES.POLICY_COUNT_ICON} alt="policy-count-icon" />}
              title="Total Policies"
              value={totalPolicies}
              color="#13C2C2"
            />
          </Col>
          <Col flex="1 0 25%" className="column">
            <CardCount
              icon={<img width="28" src={GENERIC_IMAGES.GWP_ICON} alt="gwp-icon" />}
              title="GWP"
              value={`${currency} ${new Intl.NumberFormat('id-ID', { currency: currency }).format(totalTransactionValue)}`}
              color="#13C2C2"
            />
          </Col>
          <Col flex="1 0 25%" className="column">
            <CardCount
              icon={<img width="32" src={GENERIC_IMAGES.CLAIM_AMOUNT_ICON} alt="claim-amount-icon" />}
              title="Total Claim Amount"
              value={`${currency} ${new Intl.NumberFormat('id-ID', { currency: currency }).format(totalClaimAmount)}`}
              color="#13C2C2"
            />
          </Col>
        </Row>
      </CountStyle>
    )
  }
}

export default Count