import React, { Component } from 'react'
import { connect } from 'react-redux'
import { forEach, set, find, findIndex, uniq, map } from 'lodash'
import { Card, Spin } from 'antd'
import moment from 'moment'

import { DashboardGraph, CountRow, DataTable, DashboardFilter } from './Components'
import { Header } from '../../../../components/StyledComponents'
import policyActions from '../../../redux/policy/action'
import claimsActions from '../../../redux/claims/actions'
import { DashboardStyled } from './index.style'

const { getDashboardData, getPartnersList, getProductsList, getPackagesList } = policyActions
const { getClaimDisbursementData } = claimsActions

const DATE_FORMAT = 'YYYY-MM-DD'

class Dashboard extends Component {
  constructor(props) {
    super(props)
    this.state = {
      createdAtEnd: '',
      createdAtStart: '',
      product: [],
      packages: [],
      currency: 'IDR',
    }
  }

  componentDidMount() {
    const current = moment()
    const previous = current.clone().subtract(7, 'days')
    this.setState({ createdAtStart: previous, createdAtEnd: current })
    this.fetch({
      createdatEnd: current,
      createdatStart: previous
    })
    this.props.getPartnersList()
    this.props.getProductsList()

    const config = JSON.parse(localStorage.getItem('config'))
    if (Array.isArray(config) && config?.length > 0){
      const currencyConfig = config.find((x) => x?.config_type?.name === "PROVIDER_CURRENCY") || "IDR"
      this.setState({ currency: currencyConfig?.value })
    }
  }

  fetch = (filtersData) => {
    const { createdatStart, createdatEnd, partner, product = [], packages = [] } = filtersData
    this.setState({ createdAtStart: createdatStart, createdAtEnd: createdatEnd, product, packages })
    this.props.getDashboardData({
      query: {
        ...filtersData,
        createdatStart: `${moment(createdatStart).format(DATE_FORMAT)} 00:00:00`,
        createdatEnd: `${moment(createdatEnd).format(DATE_FORMAT)} 23:59:59`,
        partnerCodes: partner,
        packageCodes: packages.join(','), 
        productKey: product.join(','),
        dashboardView: packages.length > 0 ? 'package' : product.length > 0 ? 'product' : 'partner'
      }
    })
    this.props.getClaimDisbursementData({
      query: {
        start_date: `${moment(createdatStart).format(DATE_FORMAT)} 00:00:00`,
        end_date: `${moment(createdatEnd).format(DATE_FORMAT)} 23:59:59`,
        partners: partner,
        products: product ? product.join(',') : "",
        dashboard_view: product.length > 0 ? 'product' : 'partner'
      }
    })
  }

  getDateWiseData = () => {
    const { policyDashboardData = {} } = this.props
    const { createdAtEnd, createdAtStart, product = [], packages = [] } = this.state
    const { PartnerWiseCount, ProductWiseCount, PackageWiseCount } = policyDashboardData
    let finalData = []
    if (packages.length > 0) {
      forEach(PackageWiseCount, function ({ policiesCount, package_code: packageCode, created_at: createdAt }) {
        let existingEnrtyForDate = find(finalData, { 'created_at': createdAt })
        if (existingEnrtyForDate) {
          const index = findIndex(finalData, { 'created_at': createdAt })
          set(existingEnrtyForDate, packageCode, parseInt(policiesCount))
          finalData[index] = existingEnrtyForDate
        } else {
          let dataObject = {}
          set(dataObject, 'created_at', createdAt)
          set(dataObject, packageCode, parseInt(policiesCount))
          finalData.push(dataObject)
        }
      })
    } else if (product.length > 0) {
      forEach(ProductWiseCount, function ({ policiesCount, product_key: productKey, created_at: createdAt }) {
        let existingEnrtyForDate = find(finalData, { 'created_at': createdAt })
        if (existingEnrtyForDate) {
          const index = findIndex(finalData, { 'created_at': createdAt })
          set(existingEnrtyForDate, productKey, parseInt(policiesCount))
          finalData[index] = existingEnrtyForDate
        } else {
          let dataObject = {}
          set(dataObject, 'created_at', createdAt)
          set(dataObject, productKey, parseInt(policiesCount))
          finalData.push(dataObject)
        }
      })
    } else {
      forEach(PartnerWiseCount, function ({ policiesCount, partner_key: partnerKey, created_at: createdAt }) {
        let existingEnrtyForDate = find(finalData, { 'created_at': createdAt })
        if (existingEnrtyForDate) {
          const index = findIndex(finalData, { 'created_at': createdAt })
          set(existingEnrtyForDate, partnerKey, parseInt(policiesCount))
          finalData[index] = existingEnrtyForDate
        } else {
          let dataObject = {}
          set(dataObject, 'created_at', createdAt)
          set(dataObject, partnerKey, parseInt(policiesCount))
          finalData.push(dataObject)
        }
      })
    }
    if (createdAtStart && createdAtEnd) {
      const difference = createdAtEnd.diff(createdAtStart, 'd')
      for (let i = 0; i < difference; i++) {
        let date = createdAtStart.clone().add(i, 'days').format('YYYY-MM-DD')
        if (!find(finalData, { created_at: date })) {
          finalData.push({
            'created_at': date
          })
        }
      }
    }

    // sort array based on created_at
    finalData.sort(function (a, b) {
      var keyA = new Date(a.created_at),
        keyB = new Date(b.created_at);
      // Compare the 2 dates
      if (keyA < keyB) return -1;
      if (keyA > keyB) return 1;
      return 0;
    })
    if (finalData.length > 0) {
      let obj = finalData.reduce((res, item) => ({ ...res, ...item }))

      // Get those keys as an array
      let keys = Object.keys(obj)

      // Create an object with all keys set to the default value (0)
      let def = keys.reduce((result, key) => {
        result[key] = 0
        return result
      }, {})

      // Use object destrucuring to replace all default values with the ones we have
      let result = finalData.map((item) => ({ ...def, ...item }))
      finalData = result
    }
    return finalData
  }

  getProductList = () => {
    const { policyDashboardData = {} } = this.props
    const { product = [], packages = [] } = this.state
    const { PartnerWiseCount, ProductWiseCount, PackageWiseCount } = policyDashboardData
    if (packages.length > 0) {
      return uniq(map(PackageWiseCount, 'package_code'))
    } else if (product.length > 0) {
      return uniq(map(ProductWiseCount, 'product_key'))
    }
    return uniq(map(PartnerWiseCount, 'partner_key'))
  }

  render() {
    const { policyDashboardData = {}, claimDashboardData = {}, policyDashboardLoading, claimDashboardLoading } = this.props
    const { PartnerWiseCountWithoutDateGrouping = [], TotalPolicies, TotalTransactionValue, ProductWiseCountWithoutDateGrouping = [], PackageWiseCountWithoutDateGrouping = [] } = policyDashboardData
    const { total_claim_amount: totalClaimAmount } = claimDashboardData
    const { product, currency } = this.state

    return (
      <DashboardStyled>
        <Spin spinning={!!policyDashboardLoading || !!claimDashboardLoading}>
          <CountRow
            totalClaimAmount={totalClaimAmount}
            totalPolicies={TotalPolicies}
            totalTransactionValue={TotalTransactionValue}
            currency={currency}
          />
          <Card>
            <DashboardFilter
              fetch={this.fetch}
            />
          </Card>
          <Card className='graph-card'>
            <Header content='POLICY DASHBOARD' />
            <DashboardGraph
              data={this.getDateWiseData()}
              productList={this.getProductList()}
            />
          </Card>
          <Card>
            <DataTable
              data={PartnerWiseCountWithoutDateGrouping || ProductWiseCountWithoutDateGrouping || PackageWiseCountWithoutDateGrouping}
              claimDashboardData={claimDashboardData.data}
              product={product}
            />
          </Card>
        </Spin>
      </DashboardStyled>
    )
  }
}

export default connect(state => ({
  policyDashboardData: state.Policy.policyDashboardData,
  policyDashboardLoading: state.Loading.GET_DASHBOARD_DATA,

  claimDashboardData: state.Claim.claimDashboardData,
  claimDashboardLoading: state.Loading.GET_CLAIM_DASHBOARD_DATA
}), {
  getDashboardData,
  getClaimDisbursementData,
  getPartnersList,
  getProductsList,
  getPackagesList
})(Dashboard)
